    Require-App
    $screen=[Windows.Forms.Screen]::FromHandle($hwnd).WorkingArea
    if([DcmNative]::IsIconic($hwnd) -or -not [DcmNative]::IsWindowVisible($hwnd) -or -not $script:capturePositioned){
